ALTER TABLE invoice_discount ADD COLUMN discount_cap DECIMAL(12, 2);

ALTER TABLE invoice_discount ADD CONSTRAINT invoice_discount_cap_positive CHECK (discount_cap IS NULL OR discount_cap > 0);
ALTER TABLE invoice_discount ADD CONSTRAINT invoice_discount_cap_on_pct CHECK (discount_cap IS NULL OR discount_pct > 0);
-- An invoice's discount is now either a percentage or a flat amount, never both. An invoice that had
-- both keeps what they took off together, as a flat amount, so its amount is unchanged: the
-- percentage of the subtotal plus the flat amount (never more than was left after the percentage).
CREATE VIEW invoice_subtotal_v44 AS
    SELECT i.id AS invoice_id,
           COALESCE((SELECT SUM(ROUND(l.qty * l.unit_price, 2)
                         - ROUND(ROUND(l.qty * l.unit_price, 2) * l.discount_pct / 100, 2))
                     FROM invoice_line_item l WHERE l.invoice_id = i.id), 0) AS subtotal
    FROM invoice i;

UPDATE invoice i SET
    discount_amount = (
        SELECT ROUND(v.subtotal * i.discount_pct / 100, 2)
            + LEAST(i.discount_amount, GREATEST(v.subtotal - ROUND(v.subtotal * i.discount_pct / 100, 2), 0))
        FROM invoice_subtotal_v44 v WHERE v.invoice_id = i.id),
    discount_pct = 0
WHERE i.discount_pct > 0 AND i.discount_amount > 0;

DROP VIEW invoice_subtotal_v44;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_one_kind CHECK (discount_pct = 0 OR discount_amount = 0);
-- An invoice can also take a flat amount off what its line items add up to, on top of (or instead of)
-- the percentage discount. It never takes off more than is left after the percentage. Existing
-- invoices have no flat discount, so their amounts are unchanged.
ALTER TABLE invoice ADD COLUMN discount_amount DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_amount_non_negative CHECK (discount_amount >= 0);
-- An invoice can carry a minimum charge: when its net total (after the discounts, taxes and surcharge)
-- comes out under it, the minimum is billed instead. Existing invoices have none, so their amounts are
-- unchanged.
ALTER TABLE invoice ADD COLUMN minimum_charge DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_minimum_charge_non_negative CHECK (minimum_charge >= 0);
-- The levy (the second tax) is scrapped: invoices carry only the one sales tax again, and every total
-- works out as if the levy never existed. An invoice that added a levy on top has it taken back out of
-- its stored amount (never below its minimum charge): the levy on each taxable line after its share of
-- the discounts, rounded to the cent and added up, just as it was charged. A tax-inclusive invoice owes
-- the same (the levy was inside its prices, and now only the sales tax is worked back out of them), and
-- a tax-exempt invoice never carried a levy.
CREATE VIEW invoice_levy_line_v109 AS
    SELECT l.invoice_id,
           l.tax_exempt,
           ROUND(l.qty * l.unit_price, 2) - ROUND(ROUND(l.qty * l.unit_price, 2) * l.discount_pct / 100, 2) AS line_amount
    FROM invoice_line_item l;

CREATE VIEW invoice_levy_subtotal_v109 AS
    SELECT i.id AS invoice_id,
           COALESCE((SELECT SUM(v.line_amount) FROM invoice_levy_line_v109 v WHERE v.invoice_id = i.id), 0) AS subtotal
    FROM invoice i;

-- The uncapped percentages each line takes off itself, and what the flat amounts and capped percentages
-- take off the subtotal together, shared across the lines in proportion to what each charges.
CREATE VIEW invoice_levy_discount_v109 AS
    SELECT s.invoice_id,
           s.subtotal,
           LEAST(COALESCE((SELECT SUM(d.discount_pct) FROM invoice_discount d WHERE d.invoice_id = s.invoice_id
                             AND d.discount_pct > 0
                             AND (d.discount_cap IS NULL OR ROUND(s.subtotal * d.discount_pct / 100, 2) <= d.discount_cap)), 0),
                 100) AS uncapped_pct,
           COALESCE((SELECT SUM(CASE WHEN d.discount_pct > 0 THEN d.discount_cap ELSE d.discount_amount END)
                     FROM invoice_discount d WHERE d.invoice_id = s.invoice_id
                       AND (d.discount_pct = 0
                            OR (d.discount_cap IS NOT NULL AND ROUND(s.subtotal * d.discount_pct / 100, 2) > d.discount_cap))), 0)
               AS shared_wanted
    FROM invoice_levy_subtotal_v109 s;

ALTER TABLE invoice ADD COLUMN rework_levy DECIMAL(14, 2);

UPDATE invoice i SET rework_levy = (
    SELECT COALESCE(SUM(ROUND(
               (v.line_amount
